insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('patate douce rotie', 'Patates douces rôties', array['patate douce au four']::text[], 'dish', $r$[{"title":"Patates douces rôties","intro":"Des patates douces rôties au paprika et au cumin, fondantes et caramélisées.","minutes":45,"calories":220,"difficulty":"Facile","imageSearch":"roasted sweet potatoes","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"patate douce","plural":"patates douces","qty":3,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 210 °C.","timer":null},{"text":"Coupe les patates douces en cubes sans les éplucher.","timer":null},{"text":"Mélange-les avec l'huile, le paprika, le cumin et le sel.","timer":null},{"text":"Enfourne 35 min en remuant à mi-cuisson.","timer":{"label":"Four","min":35}}],"kids":true,"variant":"La classique","change":""},{"title":"Patates douces farcies","intro":"Des patates douces au four en plat complet végétarien.","minutes":60,"calories":400,"difficulty":"Facile","imageSearch":"stuffed sweet potatoes","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"patate douce","plural":"patates douces","qty":4,"unit":"","have":false},{"name":"haricots rouges","plural":"haricots rouges","qty":250,"unit":"g","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"fromage frais","plural":"fromage frais","qty":100,"unit":"g","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Pique les patates douces et enfourne-les 50 min.","timer":{"label":"Four","min":50}},{"text":"Réchauffe les haricots rouges égouttés.","timer":null},{"text":"Coupe l'avocat en dés et arrose-le de jus de citron vert.","timer":null},{"text":"Fends les patates douces et garnis-les de haricots, d'avocat, de fromage frais et de coriandre.","timer":null}],"variant":"Farcies","change":"Cuites entières et garnies de haricots, avocat et fromage frais."},{"title":"Purée de patates douces","intro":"Une purée orange douce et veloutée.","minutes":30,"calories":240,"difficulty":"Facile","imageSearch":"sweet potato mash","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"patate douce","plural":"patates douces","qty":4,"unit":"","have":false},{"name":"lait de coco","plural":"lait de coco","qty":10,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"muscade","plural":"muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Épluche les patates douces et coupe-les en morceaux.","timer":null},{"text":"Fais-les cuire 20 min à l'eau salée.","timer":{"label":"Cuisson","min":20}},{"text":"Égoutte et écrase avec le lait de coco et le beurre.","timer":null},{"text":"Assaisonne de sel et de muscade.","timer":null}],"kids":true,"variant":"Purée","change":"En purée, au lait de coco."}]$r$::jsonb, 'claude')
