insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('oeuf benedicte', 'Œufs Bénédicte', array['oeuf benedict', 'egg benedict']::text[], 'dish', $r$[{"title":"Œufs Bénédicte","intro":"Des œufs pochés sur des muffins grillés et du bacon, nappés de sauce hollandaise.","minutes":30,"calories":520,"difficulty":"Difficile","imageSearch":"eggs benedict","veg":false,"oven":false,"cold":false,"missing":"","origin":"Brunch américain","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":7,"unit":"","have":false},{"name":"muffins anglais","plural":"muffins anglais","qty":2,"unit":"","have":false},{"name":"bacon","plural":"bacon","qty":4,"unit":"tranches","have":false},{"name":"beurre","plural":"beurres","qty":100,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"vinaigre blanc","plural":"vinaigre blanc","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais fondre le beurre. Fouette 3 jaunes d'œufs avec 2 c. à s. d'eau au bain-marie jusqu'à ce qu'ils épaississent.","timer":null},{"text":"Ajoute le beurre fondu petit à petit en fouettant, puis le jus du citron : c'est la hollandaise.","timer":null},{"text":"Fais griller les muffins coupés en deux et dorer le bacon.","timer":{"label":"Poêle","min":4}},{"text":"Poche les 4 œufs 3 min dans de l'eau frémissante vinaigrée.","timer":{"label":"Cuisson","min":3}},{"text":"Monte : muffin, bacon, œuf poché, puis la sauce.","timer":null}],"variant":"La classique","change":""},{"title":"Œufs Bénédicte au saumon","intro":"La version royale, au saumon fumé.","minutes":30,"calories":500,"difficulty":"Difficile","imageSearch":"eggs royale salmon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":7,"unit":"","have":false},{"name":"muffins anglais","plural":"muffins anglais","qty":2,"unit":"","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":4,"unit":"tranches","have":false},{"name":"beurre","plural":"beurres","qty":100,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"vinaigre blanc","plural":"vinaigre blanc","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Prépare la hollandaise au bain-marie avec 3 jaunes, le beurre fondu et le citron.","timer":null},{"text":"Fais griller les muffins coupés en deux.","timer":null},{"text":"Poche les 4 œufs 3 min dans de l'eau vinaigrée.","timer":{"label":"Cuisson","min":3}},{"text":"Monte : muffin, saumon, œuf poché, puis la sauce.","timer":null}],"variant":"Au saumon","change":"Avec du saumon fumé à la place du bacon."},{"title":"Œufs Bénédicte aux épinards","intro":"La version florentine, aux épinards.","minutes":30,"calories":450,"difficulty":"Difficile","imageSearch":"eggs florentine spinach","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":7,"unit":"","have":false},{"name":"muffins anglais","plural":"muffins anglais","qty":2,"unit":"","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":200,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":100,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"vinaigre blanc","plural":"vinaigre blanc","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Prépare la hollandaise au bain-marie avec 3 jaunes, le beurre fondu et le citron.","timer":null},{"text":"Fais fondre les épinards 2 min à la poêle.","timer":{"label":"Poêle","min":2}},{"text":"Fais griller les muffins et poche les 4 œufs 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Monte : muffin, épinards, œuf poché, puis la sauce.","timer":null}],"variant":"Végétariens","change":"Avec des épinards fondus."}]$r$::jsonb, 'claude')
