insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gyoza', 'Gyozas', array['ravioli japonai', 'ravioli chinoi', 'dumpling', 'ravioli vapeur']::text[], 'dish', $r$[{"title":"Gyozas au porc","intro":"Les raviolis japonais grillés dessous et cuits à la vapeur dessus, farcis au porc et au chou.","minutes":60,"calories":320,"difficulty":"Difficile","imageSearch":"pork gyoza dumplings","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette japonaise","serves":4,"items":[{"name":"feuilles à gyoza","plural":"feuilles à gyoza","qty":30,"unit":"","have":false},{"name":"porc haché","plural":"porc haché","qty":300,"unit":"g","have":false},{"name":"chou chinois","plural":"choux chinois","qty":0.25,"unit":"","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"huile de sésame","plural":"huile de sésame","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Hache finement le chou, sale-le et presse-le pour retirer l'eau.","timer":null},{"text":"Mélange-le avec le porc, l'ail, le gingembre, 1 c. à s. de sauce soja et l'huile de sésame.","timer":null},{"text":"Mets une cuillerée de farce sur chaque feuille, mouille le bord et plisse pour fermer.","timer":null},{"text":"Fais dorer les gyozas 3 min dans une poêle huilée.","timer":{"label":"Poêle","min":3}},{"text":"Verse 10 cl d'eau, couvre et laisse 5 min.","timer":{"label":"Vapeur","min":5}},{"text":"Sers avec le reste de sauce soja.","timer":null}],"variant":"La classique","change":""},{"title":"Gyozas aux légumes","intro":"Des gyozas végétariens au chou, carotte et tofu.","minutes":60,"calories":250,"difficulty":"Difficile","imageSearch":"vegetable gyoza","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"feuilles à gyoza","plural":"feuilles à gyoza","qty":30,"unit":"","have":false},{"name":"tofu ferme","plural":"tofu ferme","qty":150,"unit":"g","have":false},{"name":"chou chinois","plural":"choux chinois","qty":0.25,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":100,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Hache le chou, la carotte et les champignons et fais-les revenir 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Mélange avec le tofu écrasé, le gingembre et 1 c. à s. de sauce soja.","timer":null},{"text":"Garnis et ferme les feuilles.","timer":null},{"text":"Fais dorer 3 min, puis ajoute 10 cl d'eau, couvre et laisse 5 min.","timer":{"label":"Vapeur","min":5}}],"variant":"Végétariens","change":"Farcis aux légumes et au tofu."},{"title":"Gyozas aux crevettes","intro":"Des gyozas délicats aux crevettes et à la ciboulette.","minutes":60,"calories":260,"difficulty":"Difficile","imageSearch":"shrimp gyoza","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"feuilles à gyoza","plural":"feuilles à gyoza","qty":30,"unit":"","have":false},{"name":"crevette décortiquée","plural":"crevettes décortiquées","qty":300,"unit":"g","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"huile de sésame","plural":"huile de sésame","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Hache les crevettes et mélange-les avec la ciboulette, le gingembre, l'huile et 1 c. à s. de sauce soja.","timer":null},{"text":"Garnis et ferme les feuilles.","timer":null},{"text":"Fais dorer 3 min dans une poêle huilée.","timer":{"label":"Poêle","min":3}},{"text":"Ajoute 10 cl d'eau, couvre et laisse 5 min.","timer":{"label":"Vapeur","min":5}}],"variant":"Crevettes","change":"Farcis aux crevettes."}]$r$::jsonb, 'claude')
