insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pho', 'Phở', array['soupe pho', 'pho bo', 'soupe vietnamienne']::text[], 'dish', $r$[{"title":"Phở au bœuf","intro":"La soupe vietnamienne au bouillon parfumé à la badiane, avec nouilles de riz et bœuf.","minutes":60,"calories":420,"difficulty":"Moyen","imageSearch":"pho bo beef noodle soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette vietnamienne","serves":4,"items":[{"name":"nouilles de riz","plural":"nouilles de riz","qty":250,"unit":"g","have":false},{"name":"bœuf à fondue","plural":"bœuf à fondue","qty":300,"unit":"g","have":false},{"name":"bouillon de bœuf","plural":"bouillons de bœuf","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"gingembre frais","plural":"gingembre frais","qty":1,"unit":"","have":false},{"name":"badiane","plural":"badianes","qty":2,"unit":"","have":false},{"name":"sauce nuoc-mâm","plural":"sauce nuoc-mâm","qty":3,"unit":"c. à s.","have":false},{"name":"pousses de soja","plural":"pousses de soja","qty":150,"unit":"g","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais griller l'oignon et le gingembre coupés en deux à la poêle, à sec.","timer":{"label":"Poêle","min":5}},{"text":"Mets-les dans 1,5 litre d'eau avec les bouillons, la badiane et le nuoc-mâm, et laisse frémir 40 min.","timer":{"label":"Cuisson","min":40}},{"text":"Fais cuire les nouilles selon le paquet.","timer":null},{"text":"Coupe le bœuf cru en tranches très fines.","timer":null},{"text":"Mets nouilles et bœuf dans les bols et verse le bouillon bouillant dessus : il cuit la viande.","timer":null},{"text":"Sers avec les pousses de soja, la coriandre et le citron vert.","timer":null}],"variant":"La classique","change":""},{"title":"Phở au poulet","intro":"La version au poulet, plus douce.","minutes":50,"calories":380,"difficulty":"Moyen","imageSearch":"pho ga chicken noodle soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"nouilles de riz","plural":"nouilles de riz","qty":250,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"gingembre frais","plural":"gingembre frais","qty":1,"unit":"","have":false},{"name":"badiane","plural":"badianes","qty":2,"unit":"","have":false},{"name":"sauce nuoc-mâm","plural":"sauce nuoc-mâm","qty":2,"unit":"c. à s.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais griller l'oignon et le gingembre à sec.","timer":{"label":"Poêle","min":5}},{"text":"Mets-les dans 1,5 litre d'eau avec les bouillons, la badiane et le nuoc-mâm.","timer":null},{"text":"Poche le poulet 20 min dans ce bouillon, puis effiloche-le.","timer":{"label":"Cuisson","min":20}},{"text":"Fais cuire les nouilles et répartis-les dans les bols avec le poulet.","timer":null},{"text":"Verse le bouillon chaud et parsème de coriandre.","timer":null}],"variant":"Au poulet","change":"Avec du poulet poché dans le bouillon."},{"title":"Phở végétarien","intro":"Un phở parfumé sans viande, au tofu.","minutes":45,"calories":330,"difficulty":"Moyen","imageSearch":"vegetarian pho","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"nouilles de riz","plural":"nouilles de riz","qty":250,"unit":"g","have":false},{"name":"tofu ferme","plural":"tofu ferme","qty":200,"unit":"g","have":false},{"name":"champignons shiitaké","plural":"champignons shiitaké","qty":150,"unit":"g","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":2,"unit":"","have":false},{"name":"gingembre frais","plural":"gingembre frais","qty":1,"unit":"","have":false},{"name":"badiane","plural":"badianes","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais griller le gingembre à sec, puis mets-le dans 1,5 litre d'eau avec les bouillons, la badiane et la sauce soja.","timer":null},{"text":"Laisse frémir 25 min avec les champignons.","timer":{"label":"Cuisson","min":25}},{"text":"Fais dorer le tofu en dés.","timer":{"label":"Poêle","min":6}},{"text":"Fais cuire les nouilles, répartis-les avec le tofu et verse le bouillon.","timer":null}],"variant":"Végétarien","change":"Un bouillon de légumes avec tofu et champignons."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet satay', 'Poulet satay', array['satay', 'brochette satay', 'poulet sauce cacahuete', 'poulet cacahuete']::text[], 'dish', $r$[{"title":"Brochettes de poulet satay","intro":"Des brochettes de poulet marinées au curry, avec une sauce aux cacahuètes.","minutes":45,"calories":480,"difficulty":"Facile","imageSearch":"chicken satay skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette indonésienne","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"beurre de cacahuète","plural":"beurre de cacahuète","qty":4,"unit":"c. à s.","have":false},{"name":"lait de coco","plural":"lait de coco","qty":20,"unit":"cl","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Coupe le poulet en lamelles et fais-le mariner 20 min avec 10 cl de lait de coco, le curry et 1 c. à s. de sauce soja.","timer":{"label":"Repos","min":20}},{"text":"Enfile le poulet sur des brochettes et fais-les griller 10 min en les retournant.","timer":{"label":"Poêle","min":10}},{"text":"Chauffe le beurre de cacahuète avec le reste du lait de coco, de la sauce soja et le jus du citron vert.","timer":null},{"text":"Sers les brochettes avec la sauce et du riz.","timer":null}],"variant":"La classique","change":""},{"title":"Poulet satay en sauce","intro":"Un poulet crémeux à la cacahuète, avec du riz.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"peanut chicken curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"beurre de cacahuète","plural":"beurre de cacahuète","qty":4,"unit":"c. à s.","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais dorer le poulet en dés avec l'oignon et le curry.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute le lait de coco, le beurre de cacahuète et la sauce soja.","timer":null},{"text":"Laisse mijoter 10 min.","timer":{"label":"Cuisson","min":10}}],"variant":"En sauce","change":"Le poulet mijote dans la sauce cacahuète."},{"title":"Tofu satay","intro":"Des brochettes de tofu à la sauce cacahuète.","minutes":35,"calories":430,"difficulty":"Facile","imageSearch":"tofu satay","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tofu ferme","plural":"tofu ferme","qty":400,"unit":"g","have":false},{"name":"beurre de cacahuète","plural":"beurre de cacahuète","qty":4,"unit":"c. à s.","have":false},{"name":"lait de coco","plural":"lait de coco","qty":20,"unit":"cl","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"curry","plural":"curry","qty":1,"unit":"c. à c.","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Coupe le tofu en cubes et fais-le mariner 15 min avec la sauce soja et le curry.","timer":{"label":"Repos","min":15}},{"text":"Fais-le dorer 8 min à la poêle.","timer":{"label":"Poêle","min":8}},{"text":"Chauffe le beurre de cacahuète avec le lait de coco et le jus du citron vert.","timer":null},{"text":"Sers le tofu nappé de sauce, avec du riz.","timer":null}],"variant":"Végétarien","change":"Du tofu à la place du poulet."}]$r$::jsonb, 'claude')
