insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('chop suey', 'Chop suey', array['chop suey poulet', 'legume saute chinoi', 'poulet aux legume chinoi']::text[], 'dish', $r$[{"title":"Chop suey au poulet","intro":"Le sauté chinois de poulet et de légumes croquants, avec pousses de soja et sauce soja.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"chicken chop suey","veg":false,"oven":false,"cold":false,"missing":"","origin":"Inspiration chinoise","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"pousses de soja","plural":"pousses de soja","qty":200,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"chou chinois","plural":"choux chinois","qty":0.25,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à s.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe le poulet en lamelles et fais-le dorer 5 min à feu vif, puis retire-le.","timer":{"label":"Poêle","min":5}},{"text":"Fais sauter les carottes en bâtonnets, le chou et les champignons émincés 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute les pousses de soja et le poulet.","timer":null},{"text":"Délaye la fécule dans la sauce soja et 10 cl d'eau, verse et mélange jusqu'à ce que ça épaississe.","timer":null}],"variant":"La classique","change":""},{"title":"Chop suey aux crevettes","intro":"Un chop suey léger aux crevettes.","minutes":25,"calories":320,"difficulty":"Facile","imageSearch":"shrimp chop suey","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"crevette décortiquée","plural":"crevettes décortiquées","qty":400,"unit":"g","have":false},{"name":"pousses de soja","plural":"pousses de soja","qty":200,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à s.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais sauter les carottes et le poivron en lamelles 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute les crevettes et les pousses de soja, et laisse 3 min.","timer":{"label":"Poêle","min":3}},{"text":"Ajoute la sauce soja mélangée à la fécule et 10 cl d'eau, et remue jusqu'à ce que ça épaississe.","timer":null}],"variant":"Crevettes","change":"Les crevettes remplacent le poulet."},{"title":"Chop suey végétarien","intro":"Un sauté de légumes croquants au tofu.","minutes":25,"calories":300,"difficulty":"Facile","imageSearch":"vegetable chop suey tofu","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tofu ferme","plural":"tofu ferme","qty":300,"unit":"g","have":false},{"name":"pousses de soja","plural":"pousses de soja","qty":200,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"chou chinois","plural":"choux chinois","qty":0.25,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à s.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais dorer le tofu en dés et retire-le.","timer":{"label":"Poêle","min":6}},{"text":"Fais sauter les carottes, le brocoli et le chou 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute les pousses de soja, le tofu et la sauce soja épaissie à la fécule.","timer":null}],"variant":"Végétarien","change":"Avec du tofu et plus de légumes."}]$r$::jsonb, 'claude')
