insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tarte flambee', 'Tarte flambée', array['flammekueche', 'flammenkuche', 'flamenkuche', 'tarte flambee alsacienne']::text[], 'dish', $r$[{"title":"Tarte flambée","intro":"La pâte très fine d'Alsace, avec crème, oignons et lardons, cuite à four très chaud.","minutes":40,"calories":520,"difficulty":"Facile","imageSearch":"flammekueche","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité alsacienne","serves":4,"items":[{"name":"pâte à pizza","plural":"pâtes à pizza","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":200,"unit":"g","have":false},{"name":"muscade","plural":"muscade","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 250 °C.","timer":null},{"text":"Mélange le fromage blanc, la crème, du sel, du poivre et un peu de muscade.","timer":null},{"text":"Étale les pâtes très finement sur des plaques et couvre de ce mélange.","timer":null},{"text":"Répartis les oignons en fines lamelles et les lardons.","timer":null},{"text":"Enfourne 12 min.","timer":{"label":"Four","min":12}}],"kids":true,"variant":"La classique","change":""},{"title":"Tarte flambée gratinée","intro":"La tarte flambée gratinée, encore plus fondante.","minutes":40,"calories":600,"difficulty":"Facile","imageSearch":"gratinee flammekueche cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte à pizza","plural":"pâtes à pizza","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":200,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":100,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 250 °C.","timer":null},{"text":"Étale les pâtes finement et couvre du mélange fromage blanc et crème.","timer":null},{"text":"Ajoute les oignons, les lardons et l'emmental.","timer":null},{"text":"Enfourne 12 min.","timer":{"label":"Four","min":12}}],"kids":true,"variant":"Gratinée","change":"Avec de l'emmental sur le dessus."},{"title":"Tarte flambée au chèvre","intro":"Une tarte flambée végétarienne au chèvre et aux oignons.","minutes":35,"calories":480,"difficulty":"Facile","imageSearch":"goat cheese flatbread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte à pizza","plural":"pâtes à pizza","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":200,"unit":"g","have":false},{"name":"bûche de chèvre","plural":"bûches de chèvre","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":2,"unit":"","have":false},{"name":"miel","plural":"miels","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 250 °C.","timer":null},{"text":"Étale les pâtes finement et couvre de fromage blanc.","timer":null},{"text":"Ajoute les oignons émincés et les rondelles de chèvre.","timer":null},{"text":"Enfourne 12 min et arrose de miel en sortant.","timer":{"label":"Four","min":12}}],"variant":"Végétarienne","change":"Avec du chèvre et du miel, sans lardons."}]$r$::jsonb, 'claude')
