insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('bouillabaisse', 'Bouillabaisse', array['soupe de poisson', 'bouillabaisse marseillaise']::text[], 'dish', $r$[{"title":"Bouillabaisse","intro":"La soupe de poissons marseillaise au safran, avec sa rouille et ses croûtons.","minutes":75,"calories":480,"difficulty":"Difficile","imageSearch":"bouillabaisse","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité marseillaise","serves":4,"items":[{"name":"filets de poisson blanc","plural":"filets de poisson blanc","qty":800,"unit":"g","have":false},{"name":"moule","plural":"moules","qty":500,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":4,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"fenouil","plural":"fenouils","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"safran","plural":"safran","qty":null,"unit":"","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":4,"unit":"c. à s.","have":false},{"name":"baguette","plural":"baguettes","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais revenir les oignons, le fenouil émincé et 2 gousses d'ail dans l'huile d'olive.","timer":null},{"text":"Ajoute les tomates en dés, le safran et 1,5 litre d'eau, et laisse cuire 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les pommes de terre en rondelles et laisse 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute les poissons en morceaux et les moules, et laisse 8 min.","timer":{"label":"Cuisson","min":8}},{"text":"Mélange la mayonnaise avec l'ail restant écrasé et un peu de safran : c'est la rouille.","timer":null},{"text":"Sers avec la baguette grillée et la rouille.","timer":null}],"variant":"La classique","change":""},{"title":"Soupe de poissons","intro":"La soupe de poissons veloutée, avec croûtons et fromage.","minutes":50,"calories":350,"difficulty":"Moyen","imageSearch":"fish soup rouille","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filets de poisson blanc","plural":"filets de poisson blanc","qty":600,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"fenouil","plural":"fenouils","qty":1,"unit":"","have":false},{"name":"safran","plural":"safran","qty":null,"unit":"","have":false},{"name":"concentré de tomate","plural":"concentré de tomate","qty":1,"unit":"c. à s.","have":false},{"name":"baguette","plural":"baguettes","qty":1,"unit":"","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false}],"steps":[{"text":"Fais revenir les oignons et le fenouil, puis ajoute les tomates et le concentré.","timer":null},{"text":"Ajoute 1,2 litre d'eau, le safran et le poisson, et laisse cuire 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Mixe finement et filtre si tu veux.","timer":null},{"text":"Sers avec la baguette grillée et l'emmental.","timer":null}],"variant":"Mixée","change":"Les poissons sont mixés en velouté."},{"title":"Bouillabaisse facile","intro":"Une bouillabaisse simplifiée pour la semaine.","minutes":40,"calories":400,"difficulty":"Facile","imageSearch":"easy fish stew saffron","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dos de cabillaud","plural":"dos de cabillaud","qty":4,"unit":"","have":false},{"name":"crevette décortiquée","plural":"crevettes décortiquées","qty":200,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":3,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"safran","plural":"safran","qty":null,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false}],"steps":[{"text":"Fais revenir l'oignon et l'ail, ajoute les tomates, le safran et 80 cl d'eau.","timer":null},{"text":"Ajoute les pommes de terre en rondelles et laisse 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute le cabillaud en morceaux et les crevettes, et laisse 6 min.","timer":{"label":"Cuisson","min":6}},{"text":"Sers avec du pain grillé.","timer":null}],"variant":"Facile","change":"Avec du cabillaud et des crevettes, en moins de temps."}]$r$::jsonb, 'claude')
