insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('potee auvergnate', 'Potée auvergnate', array['potee', 'potee au chou', 'chou au lard']::text[], 'dish', $r$[{"title":"Potée auvergnate","intro":"Le chou, les légumes et le porc salé mijotés ensemble pour un plat d'hiver complet.","minutes":150,"calories":650,"difficulty":"Facile","imageSearch":"potee auvergnate cabbage pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité auvergnate","serves":4,"items":[{"name":"chou vert","plural":"choux verts","qty":1,"unit":"","have":false},{"name":"palette de porc demi-sel","plural":"palettes de porc demi-sel","qty":1,"unit":"","have":false},{"name":"saucisse de Morteau","plural":"saucisses de Morteau","qty":1,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":6,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":4,"unit":"","have":false},{"name":"navet","plural":"navets","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais dessaler la palette 2 h dans l'eau froide.","timer":null},{"text":"Mets-la dans un grand faitout d'eau froide avec l'oignon et le bouquet garni, et laisse cuire 1 h.","timer":{"label":"Cuisson","min":60}},{"text":"Ajoute le chou en quartiers blanchi 5 min, les carottes et les navets.","timer":null},{"text":"Laisse cuire 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Ajoute les pommes de terre et la saucisse piquée, et laisse 30 min.","timer":{"label":"Cuisson","min":30}}],"variant":"La classique","change":""},{"title":"Potée aux saucisses","intro":"Une potée simplifiée pour la semaine.","minutes":60,"calories":580,"difficulty":"Facile","imageSearch":"cabbage sausage stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chou vert","plural":"choux verts","qty":1,"unit":"","have":false},{"name":"saucisse de Toulouse","plural":"saucisses de Toulouse","qty":4,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":6,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false}],"steps":[{"text":"Coupe le chou en lanières et blanchis-le 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Fais dorer les saucisses dans une cocotte.","timer":{"label":"Cuisson","min":6}},{"text":"Ajoute le chou, les carottes, les pommes de terre, l'oignon, le bouillon et 50 cl d'eau.","timer":null},{"text":"Couvre et laisse mijoter 40 min.","timer":{"label":"Cuisson","min":40}}],"variant":"Aux saucisses","change":"Seulement avec des saucisses, plus rapide."},{"title":"Potée de légumes","intro":"Une potée réconfortante aux légumes d'hiver.","minutes":50,"calories":320,"difficulty":"Facile","imageSearch":"vegetable cabbage stew","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chou vert","plural":"choux verts","qty":0.5,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":4,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":2,"unit":"","have":false},{"name":"haricots blancs","plural":"haricots blancs","qty":400,"unit":"g","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false}],"steps":[{"text":"Coupe tous les légumes en morceaux.","timer":null},{"text":"Mets-les dans une cocotte avec le bouillon et 1 litre d'eau.","timer":null},{"text":"Laisse mijoter 35 min.","timer":{"label":"Cuisson","min":35}},{"text":"Ajoute les haricots blancs et laisse 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"Végétarienne","change":"Sans viande, avec des haricots blancs."}]$r$::jsonb, 'claude')
