insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pate au thon', 'Pâtes au thon', array['pate thon', 'pate thon tomate', 'spaghetti au thon']::text[], 'dish', $r$[{"title":"Pâtes au thon et à la tomate","intro":"Des pâtes dans une sauce tomate au thon, à l'ail et aux câpres : le repas des soirs pressés.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"tuna tomato pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":400,"unit":"g","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":280,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"câpres","plural":"câpres","qty":1,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Cuisson","min":10}},{"text":"Fais revenir l'oignon et l'ail dans l'huile.","timer":null},{"text":"Ajoute les tomates et laisse mijoter 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute le thon émietté et les câpres, et mélange aux pâtes.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Pâtes au thon à la crème","intro":"Des pâtes au thon crémeuses, au citron et à la ciboulette.","minutes":20,"calories":580,"difficulty":"Facile","imageSearch":"creamy tuna pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":400,"unit":"g","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":280,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":30,"unit":"g","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Cuisson","min":10}},{"text":"Chauffe la crème avec le zeste du citron.","timer":null},{"text":"Ajoute le thon émietté et un peu de jus de citron.","timer":null},{"text":"Mélange aux pâtes avec la ciboulette et le parmesan.","timer":null}],"kids":true,"variant":"À la crème","change":"Une sauce crème au citron à la place de la tomate."},{"title":"Pâtes au thon gratinées","intro":"Un gratin de pâtes au thon, simple et familial.","minutes":35,"calories":600,"difficulty":"Facile","imageSearch":"tuna pasta bake","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":350,"unit":"g","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":280,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais cuire les pâtes 2 min de moins que le paquet.","timer":{"label":"Cuisson","min":8}},{"text":"Mélange les pâtes, les tomates et le thon dans un plat.","timer":null},{"text":"Couvre de mozzarella et d'emmental.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"kids":true,"variant":"Gratinées","change":"Gratinées au four avec du fromage."}]$r$::jsonb, 'claude')
