insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pate au poulet', 'Pâtes au poulet', array['pate poulet', 'pate poulet creme', 'tagliatelle au poulet']::text[], 'dish', $r$[{"title":"Pâtes au poulet à la crème","intro":"Des tagliatelles avec du poulet doré et une sauce crème aux champignons.","minutes":30,"calories":620,"difficulty":"Facile","imageSearch":"creamy chicken pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tagliatelles","plural":"tagliatelles","qty":400,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":30,"unit":"g","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Cuisson","min":10}},{"text":"Fais dorer le poulet en dés 6 min, puis retire-le.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir l'échalote et les champignons émincés 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute la crème et le poulet, et laisse 3 min.","timer":null},{"text":"Mélange aux pâtes et parsème de parmesan.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Pâtes au poulet et pesto","intro":"Des pâtes au poulet légères, au pesto.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"pesto chicken pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":400,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"c. à s.","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":250,"unit":"g","have":false},{"name":"parmesan","plural":"parmesans","qty":30,"unit":"g","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Cuisson","min":10}},{"text":"Fais dorer le poulet en dés 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute les tomates cerises coupées en deux et laisse 2 min.","timer":null},{"text":"Mélange aux pâtes avec le pesto et le parmesan.","timer":null}],"variant":"Pesto","change":"Avec du pesto et des tomates cerises."},{"title":"Pâtes au poulet et au citron","intro":"Des pâtes fraîches au poulet, citron et épinards.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"lemon chicken pasta spinach","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":400,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":100,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Cuisson","min":10}},{"text":"Fais dorer le poulet en dés avec l'ail dans l'huile.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute les épinards, le zeste et le jus du citron.","timer":null},{"text":"Mélange aux pâtes avec un peu d'eau de cuisson.","timer":null}],"variant":"Citron","change":"Une sauce légère au citron et aux épinards."}]$r$::jsonb, 'claude')
