insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('aubergine a la parmesane', 'Aubergines à la parmesane', array['parmigiana', 'aubergine parmigiana', 'gratin d aubergine', 'melanzane']::text[], 'dish', $r$[{"title":"Aubergines à la parmigiana","intro":"Des tranches d'aubergine grillées en couches avec sauce tomate, mozzarella et parmesan.","minutes":75,"calories":420,"difficulty":"Moyen","imageSearch":"eggplant parmigiana","veg":true,"oven":true,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":2,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":80,"unit":"g","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false}],"steps":[{"text":"Coupe les aubergines en tranches, badigeonne d'huile et fais-les griller au four 20 min à 200 °C.","timer":{"label":"Four","min":20}},{"text":"Fais mijoter les tomates avec l'ail 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Alterne dans un plat : sauce, aubergines, mozzarella, parmesan et basilic.","timer":null},{"text":"Termine par la sauce, la mozzarella et le parmesan.","timer":null},{"text":"Enfourne 30 min à 180 °C.","timer":{"label":"Four","min":30}}],"variant":"La classique","change":""},{"title":"Gratin d'aubergines à la viande","intro":"Un gratin d'aubergines généreux, comme une moussaka rapide.","minutes":75,"calories":520,"difficulty":"Moyen","imageSearch":"eggplant beef bake","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":400,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":600,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":50,"unit":"g","have":false}],"steps":[{"text":"Fais griller les aubergines en tranches au four 20 min.","timer":{"label":"Four","min":20}},{"text":"Fais revenir l'oignon et le bœuf, puis ajoute les tomates et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Alterne aubergines et viande dans un plat.","timer":null},{"text":"Couvre de mozzarella et de parmesan, et enfourne 25 min à 180 °C.","timer":{"label":"Four","min":25}}],"variant":"À la viande","change":"Avec une couche de bœuf haché."},{"title":"Aubergines farcies à l'italienne","intro":"Des demi-aubergines garnies de tomate et mozzarella.","minutes":55,"calories":350,"difficulty":"Facile","imageSearch":"stuffed eggplant italian","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":2,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":40,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Coupe les aubergines en deux et quadrille la chair.","timer":null},{"text":"Enfourne 25 min, puis évide-les à moitié.","timer":{"label":"Four","min":25}},{"text":"Mélange la chair avec les tomates en dés, l'ail et le basilic.","timer":null},{"text":"Remplis les aubergines, couvre de mozzarella et de parmesan, et enfourne 15 min.","timer":{"label":"Four","min":15}}],"variant":"Farcies","change":"Les aubergines coupées en deux sont farcies."}]$r$::jsonb, 'claude')
