insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('polenta', 'Polenta', array['polenta cremeuse', 'polenta grillee', 'frite de polenta']::text[], 'dish', $r$[{"title":"Polenta crémeuse au parmesan","intro":"Une polenta onctueuse au parmesan et au beurre, à servir avec une viande en sauce.","minutes":15,"calories":320,"difficulty":"Facile","imageSearch":"creamy polenta","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"polenta précuite","plural":"polenta précuite","qty":250,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesans","qty":60,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Porte à ébullition le lait avec 50 cl d'eau salée.","timer":null},{"text":"Verse la polenta en pluie en fouettant.","timer":null},{"text":"Laisse cuire 5 min en remuant.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute le parmesan et le beurre hors du feu.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Polenta grillée","intro":"Des parts de polenta croustillantes, avec une sauce tomate.","minutes":30,"calories":300,"difficulty":"Facile","imageSearch":"grilled polenta squares","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"polenta précuite","plural":"polenta précuite","qty":250,"unit":"g","have":false},{"name":"parmesan","plural":"parmesans","qty":50,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false}],"steps":[{"text":"Fais cuire la polenta dans 1 litre d'eau salée 5 min, ajoute le parmesan.","timer":{"label":"Cuisson","min":5}},{"text":"Étale-la sur 2 cm dans un plat et laisse refroidir 1 h.","timer":null},{"text":"Coupe en parts et fais-les dorer à la poêle dans l'huile.","timer":{"label":"Poêle","min":8}},{"text":"Sers avec la sauce tomate chauffée.","timer":null}],"kids":true,"variant":"Grillée","change":"Refroidie, coupée en parts et dorée à la poêle."},{"title":"Polenta aux champignons","intro":"Une polenta crémeuse coiffée de champignons.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"polenta mushrooms","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"polenta précuite","plural":"polenta précuite","qty":250,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":400,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesans","qty":50,"unit":"g","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir les échalotes et les champignons émincés 10 min, puis ajoute la crème.","timer":{"label":"Poêle","min":10}},{"text":"Fais cuire la polenta dans 1 litre d'eau salée 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute le parmesan à la polenta.","timer":null},{"text":"Sers la polenta avec les champignons et le persil.","timer":null}],"variant":"Champignons","change":"Avec une poêlée de champignons à la crème."}]$r$::jsonb, 'claude')
