insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('saltimbocca', 'Saltimbocca', array['saltimbocca a la romaine', 'escalope jambon sauge']::text[], 'dish', $r$[{"title":"Saltimbocca de veau","intro":"Des escalopes de veau fines avec jambon cru et sauge, poêlées et déglacées au vin blanc.","minutes":25,"calories":380,"difficulty":"Moyen","imageSearch":"veal saltimbocca","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"escalope de veau","plural":"escalopes de veau","qty":4,"unit":"","have":false},{"name":"jambon cru","plural":"jambon cru","qty":4,"unit":"tranches","have":false},{"name":"sauge","plural":"sauge","qty":8,"unit":"feuilles","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Aplatis les escalopes et coupe-les en deux.","timer":null},{"text":"Pose sur chacune une demi-tranche de jambon et une feuille de sauge, fixée avec un pic.","timer":null},{"text":"Farine légèrement le côté viande.","timer":null},{"text":"Fais dorer 2 min de chaque côté dans le beurre.","timer":{"label":"Poêle","min":4}},{"text":"Déglace au vin blanc et laisse réduire 2 min.","timer":null}],"variant":"La classique","change":""},{"title":"Saltimbocca de poulet","intro":"Le saltimbocca au poulet, moins cher et tout aussi bon.","minutes":30,"calories":360,"difficulty":"Facile","imageSearch":"chicken saltimbocca","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"jambon cru","plural":"jambon cru","qty":4,"unit":"tranches","have":false},{"name":"sauge","plural":"sauge","qty":8,"unit":"feuilles","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Ouvre les blancs en deux et aplatis-les.","timer":null},{"text":"Pose le jambon et la sauge, et fixe avec un pic.","timer":null},{"text":"Fais dorer 4 min de chaque côté dans le beurre.","timer":{"label":"Poêle","min":8}},{"text":"Déglace au vin blanc et laisse réduire.","timer":null}],"variant":"Au poulet","change":"Avec des blancs de poulet aplatis."},{"title":"Saltimbocca de dinde au citron","intro":"Des escalopes de dinde au jambon cru, sauce citron.","minutes":25,"calories":320,"difficulty":"Facile","imageSearch":"turkey saltimbocca lemon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"escalope de dinde","plural":"escalopes de dinde","qty":4,"unit":"","have":false},{"name":"jambon cru","plural":"jambon cru","qty":4,"unit":"tranches","have":false},{"name":"sauge","plural":"sauge","qty":8,"unit":"feuilles","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false}],"steps":[{"text":"Pose le jambon et la sauge sur les escalopes et fixe avec un pic.","timer":null},{"text":"Fais dorer 3 min de chaque côté dans le beurre.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute le jus du citron et 5 cl d'eau.","timer":null},{"text":"Laisse réduire 1 min et sers.","timer":null}],"variant":"Dinde citron","change":"Avec de la dinde et une sauce au citron."}]$r$::jsonb, 'claude')
