insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('saint jacque poelee', 'Saint-Jacques poêlées', array['saint jacque', 'coquille saint jacque', 'noi de saint jacque', 'st jacque']::text[], 'dish', $r$[{"title":"Saint-Jacques poêlées","intro":"Des noix de Saint-Jacques saisies au beurre, dorées dehors et nacrées dedans.","minutes":15,"calories":250,"difficulty":"Moyen","imageSearch":"seared scallops","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"noix de Saint-Jacques","plural":"noix de Saint-Jacques","qty":16,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Sèche bien les noix sur du papier absorbant.","timer":null},{"text":"Fais chauffer le beurre jusqu'à ce qu'il mousse.","timer":null},{"text":"Saisis les noix 1 min 30 de chaque côté sans les bouger.","timer":{"label":"Poêle","min":3}},{"text":"Arrose de jus de citron, sale et parsème de persil.","timer":null}],"variant":"La classique","change":""},{"title":"Saint-Jacques à la crème","intro":"Des Saint-Jacques nappées d'une sauce crème délicate.","minutes":20,"calories":350,"difficulty":"Moyen","imageSearch":"scallops cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"noix de Saint-Jacques","plural":"noix de Saint-Jacques","qty":16,"unit":"","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"vin blanc","plural":"vin blanc","qty":5,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false}],"steps":[{"text":"Saisis les noix 1 min 30 de chaque côté dans le beurre et retire-les.","timer":{"label":"Poêle","min":3}},{"text":"Fais revenir les échalotes, puis déglace au vin blanc.","timer":null},{"text":"Ajoute la crème et laisse réduire 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Remets les noix 30 secondes dans la sauce.","timer":null}],"variant":"À la crème","change":"Avec une sauce crème aux échalotes."},{"title":"Coquilles Saint-Jacques gratinées","intro":"Les coquilles gratinées des repas de fête.","minutes":40,"calories":380,"difficulty":"Moyen","imageSearch":"coquilles saint jacques gratinees","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"noix de Saint-Jacques","plural":"noix de Saint-Jacques","qty":12,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"chapelure","plural":"chapelure","qty":2,"unit":"c. à s.","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four en position gril.","timer":null},{"text":"Fais revenir l'échalote et les champignons émincés 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute la crème et laisse réduire 3 min.","timer":null},{"text":"Répartis les noix coupées en deux dans 4 coquilles et nappe de sauce.","timer":null},{"text":"Parsème de chapelure et de beurre, et fais gratiner 6 min.","timer":{"label":"Four","min":6}}],"variant":"Gratinées","change":"En coquilles, avec une sauce et de la chapelure."}]$r$::jsonb, 'claude')
