insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('curry de poisson', 'Curry de poisson', array['curry poisson', 'poisson au curry', 'poisson coco']::text[], 'dish', $r$[{"title":"Curry de poisson au lait de coco","intro":"Du poisson blanc mijoté dans une sauce coco au curry, avec du riz.","minutes":30,"calories":420,"difficulty":"Facile","imageSearch":"fish coconut curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filets de poisson blanc","plural":"filets de poisson blanc","qty":600,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais revenir l'oignon avec le curry et le gingembre.","timer":null},{"text":"Ajoute les tomates en dés et le lait de coco, et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute le poisson en gros morceaux et laisse 6 min sans trop remuer.","timer":{"label":"Cuisson","min":6}},{"text":"Parsème de coriandre.","timer":null}],"variant":"La classique","change":""},{"title":"Curry de poisson et crevettes","intro":"Un curry de la mer plus généreux.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"fish shrimp curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filets de poisson blanc","plural":"filets de poisson blanc","qty":400,"unit":"g","have":false},{"name":"crevette décortiquée","plural":"crevettes décortiquées","qty":200,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais revenir l'oignon avec le curry, puis ajoute le lait de coco.","timer":null},{"text":"Ajoute le poisson et les crevettes, et laisse 6 min.","timer":{"label":"Cuisson","min":6}},{"text":"Sers avec le riz.","timer":null}],"variant":"Avec crevettes","change":"Avec des crevettes en plus."},{"title":"Curry de poisson à la tomate","intro":"Un curry de poisson plus léger à la tomate.","minutes":30,"calories":320,"difficulty":"Facile","imageSearch":"fish tomato curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filets de poisson blanc","plural":"filets de poisson blanc","qty":600,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais revenir l'oignon, l'ail et le curry.","timer":null},{"text":"Ajoute les tomates et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute le poisson et laisse 6 min.","timer":{"label":"Cuisson","min":6}}],"variant":"Sans coco","change":"Une sauce tomate épicée, sans lait de coco."}]$r$::jsonb, 'claude')
