e le four à 200 °C.","timer":null},{"text":"Étale les tomates en rondelles, l'oignon et l'ail dans un plat.","timer":null},{"text":"Pose les sardines dessus, arrose d'huile et parsème de thym.","timer":null},{"text":"Enfourne 15 min.","timer":{"label":"Four","min":15}}],"variant":"Au four","change":"Cuites au four sur des tomates et oignons."},{"title":"Filets de sardines marinés","intro":"Des sardines marinées à servir en entrée fraîche.","minutes":20,"calories":240,"difficulty":"Moyen","imageSearch":"marinated sardine fillets","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"filet de sardine","plural":"filets de sardines","qty":16,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":3,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Pose les filets dans un plat, côté peau dessous.","timer":null},{"text":"Arrose du jus des citrons et laisse 1 h au frais.","timer":null},{"text":"Égoutte, arrose d'huile d'olive.","timer":null},{"text":"Parsème d'échalote hachée et de persil.","timer":null}],"variant":"Marinés","change":"Des filets crus marinés au citron."}]$r$::jsonb, 'claude')
