insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tofu saute', 'Tofu sauté', array['tofu croustillant', 'tofu poele', 'tofu grille', 'tofu saute aux legume']::text[], 'dish', $r$[{"title":"Tofu sauté aux légumes","intro":"Du tofu doré et croustillant, sauté avec des légumes et une sauce soja-gingembre.","minutes":25,"calories":350,"difficulty":"Facile","imageSearch":"crispy tofu stir fry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Inspiration asiatique","serves":4,"items":[{"name":"tofu ferme","plural":"tofu ferme","qty":400,"unit":"g","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":2,"unit":"c. à s.","have":false},{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"huile","plural":"huile","qty":3,"unit":"c. à s.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe le tofu en cubes, sèche-le et roule-le dans la fécule.","timer":null},{"text":"Fais-le dorer 8 min dans l'huile chaude, puis retire-le.","timer":{"label":"Poêle","min":8}},{"text":"Fais sauter le brocoli et le poivron 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Remets le tofu avec la sauce soja et le gingembre, et mélange 1 min.","timer":null}],"variant":"La classique","change":""},{"title":"Tofu au caramel","intro":"Le tofu à la vietnamienne, sucré-salé.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"caramelized tofu","veg":true,"oven":false,"cold":false,"missing":"","origin":"Inspiration vietnamienne","serves":4,"items":[{"name":"tofu ferme","plural":"tofu ferme","qty":400,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":3,"unit":"","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais dorer le tofu en cubes à la poêle.","timer":{"label":"Poêle","min":8}},{"text":"Fais un caramel avec le sucre, puis ajoute la sauce soja, l'ail et 5 cl d'eau.","timer":null},{"text":"Ajoute le tofu et laisse réduire jusqu'à ce qu'il soit laqué. Parsème d'oignon.","timer":null}],"variant":"Au caramel","change":"Laqué dans une sauce caramel au soja."},{"title":"Tofu au curry","intro":"Un curry de tofu doux au lait de coco.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"tofu coconut curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tofu ferme","plural":"tofu ferme","qty":400,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":100,"unit":"g","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais dorer le tofu en cubes et retire-le.","timer":{"label":"Poêle","min":8}},{"text":"Fais revenir l'oignon avec le curry, ajoute le lait de coco et laisse 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute le tofu et les épinards, et laisse 3 min.","timer":null}],"variant":"Au curry","change":"Mijoté dans une sauce curry coco."}]$r$::jsonb, 'claude')
