"text":"Ajoute la crème et la muscade.","timer":null},{"text":"Creuse 4 puits et casse un œuf dans chacun.","timer":null},{"text":"Couvre et laisse 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"Avec des œufs","change":"Des œufs cuits au milieu des épinards."},{"title":"Gratin d'épinards","intro":"Des épinards à la crème gratinés à l'emmental.","minutes":30,"calories":240,"difficulty":"Facile","imageSearch":"spinach gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"épinards surgelés","plural":"épinards surgelés","qty":600,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"muscade","plural":"muscade","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Fais décongeler les épinards et presse-les.","timer":null},{"text":"Mélange avec la crème, l'œuf et la muscade, et verse dans un plat.","timer":null},{"text":"Couvre d'emmental et enfourne 20 min.","timer":{"label":"Four","min":20}}],"kids":true,"variant":"Gratiné","change":"Gratinés au four au fromage."}]$r$::jsonb, 'claude')
